begin;
set local lock_timeout = '3s';
set local statement_timeout = '60s';
do $$ begin
  if current_setting('transaction_read_only')::boolean then raise exception 'CONTENT_LOAD_READ_ONLY_TRANSACTION'; end if;
  if not exists (select 1 from information_schema.columns where table_schema='public' and table_name='tec_english_exercises' and column_name='skill_code') then raise exception 'TEC_LANGUAGE_V2_SCHEMA_REQUIRED'; end if;
end $$;
create temporary table _tec_lang_courses (course_code text, content_version int, title text, description text, author text, publication_status text, review_status text, xp_per_lesson int, is_test_fixture boolean) on commit drop;
create temporary table _tec_lang_units (id text, course_code text, position int, title text, description text, content_version int, author text, publication_status text, review_status text) on commit drop;
create temporary table _tec_lang_lessons (id text, unit_id text, position int, title text, introduction text, xp_reward int, content_version int, author text, publication_status text, review_status text) on commit drop;

Na estação, escute a pergunta sobre o destino e diga se precisa de uma passagem só de ida. “Platform” é a plataforma de embarque.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u1-l2', 'en-v2x-unit-1', '2', 'No ônibus', 'Objetivo: Perguntar onde pegar um ônibus e entender o número da linha.

Use “Which bus…” para perguntar qual ônibus leva a um lugar. “Stop” é o ponto de ônibus.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u1-l3', 'en-v2x-unit-1', '3', 'No hotel', 'Objetivo: Informar uma reserva e pedir detalhes simples sobre o quarto.

No check-in, diga o nome da reserva. “Reservation” significa reserva e “key card” é o cartão-chave.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u1-l4', 'en-v2x-unit-1', '4', 'Comprando uma passagem', 'Objetivo: Perguntar sobre disponibilidade e escolher um horário para viajar.

“Available” significa disponível. Para confirmar uma escolha, diga “That time works for me.”', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u2-l1', 'en-v2x-unit-2', '1', 'No café', 'Objetivo: Pedir comida e bebida com cortesia usando “would like”.

“I’d like…” é uma forma educada de pedir. “Still water” é água sem gás.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u2-l2', 'en-v2x-unit-2', '2', 'No restaurante', 'Objetivo: Fazer um pedido e confirmar um ingrediente de um prato.

Pergunte “Does this dish have…?” para conferir ingredientes. “Without” significa sem.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u2-l3', 'en-v2x-unit-2', '3', 'Preferências alimentares', 'Objetivo: Expressar uma preferência alimentar e pedir uma alternativa.

“I prefer…” expressa preferência. Para recusar algo com gentileza, explique o que prefere.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u2-l4', 'en-v2x-unit-2', '4', 'Na feira', 'Objetivo: Perguntar o preço e comprar uma quantidade de frutas.

Use “How much…” para perguntar o preço. “A kilo of” indica um quilo de algo.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u3-l1', 'en-v2x-unit-3', '1', 'A previsão do tempo', 'Objetivo: Entender uma previsão simples e perguntar sobre o clima.

“Forecast” é previsão do tempo. As expressões “It is sunny” e “It is cloudy” descrevem o clima.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u3-l2', 'en-v2x-unit-3', '2', 'Roupas para o clima', 'Objetivo: Relacionar roupas e clima usando recomendações simples.

“You should…” é usado para dar uma recomendação. “Raincoat” significa capa de chuva.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u3-l3', 'en-v2x-unit-3', '3', 'Na farmácia', 'Objetivo: Explicar um sintoma e pedir orientação básica na farmácia.

“I have a…” introduz alguns sintomas. “Sore throat” significa dor de garganta.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u3-l4', 'en-v2x-unit-3', '4', 'Pedindo ajuda', 'Objetivo: Pedir ajuda e informar um sintoma ou uma necessidade imediata.

“Could you help me?” é um pedido educado. “I feel dizzy” significa estou me sentindo tonto ou tonta.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u4-l1', 'en-v2x-unit-4', '1', 'Fazendo um convite', 'Objetivo: Fazer um convite usando “Would you like to…?”.

“Would you like to…” é uma forma cordial de convidar alguém. “Sounds good” aceita uma ideia.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u4-l2', 'en-v2x-unit-4', '2', 'Combinando horários', 'Objetivo: Sugerir e confirmar um horário para uma atividade.

“Are you free…?” pergunta se alguém está disponível. “At half past three” indica três e meia.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u4-l3', 'en-v2x-unit-4', '3', 'Compartilhando opiniões', 'Objetivo: Expressar uma opinião e perguntar a opinião de outra pessoa.

“I think…” introduz uma opinião. “Interesting” significa interessante.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('en-v2x-u4-l4', 'en-v2x-unit-4', '4', 'Resolvendo um imprevisto', 'Objetivo: Relatar um pequeno imprevisto e propor uma alternativa.

“There is a problem with…” apresenta um problema. “Could we…?” propõe uma solução com cortesia.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('es-v1-u1-l1', 'es-v1-unit-1', '1', 'Cumprimentos', 'Objetivo: Cumprimentar, perguntar como alguém está e despedir-se.

“Hola” funciona em qualquer momento. “Buenos días” é usado pela manhã e “Buenas tardes” à tarde.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('es-v1-u1-l2', 'es-v1-unit-1', '2', 'Apresentações', 'Objetivo: Apresentar-se e perguntar o nome com formas naturais em espanhol.

“Me llamo…” significa “me chamo…”. Para perguntar o nome, use “¿Cómo te llamas?”.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('es-v1-u1-l3', 'es-v1-unit-1', '3', 'De onde você é?', 'Objetivo: Perguntar de onde alguém é e responder com país ou cidade.

“¿De dónde eres?” pergunta a origem. “Soy de…” indica de onde você é.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('es-v1-u1-l4', 'es-v1-unit-1', '4', 'Frases de cortesia', 'Objetivo: Usar “por favor”, “gracias” e “de nada” em pedidos simples.

“Por favor” acompanha um pedido; “gracias” agradece e “de nada” responde ao agradecimento.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('es-v1-u2-l1', 'es-v1-unit-2', '1', 'No café', 'Objetivo: Fazer um pedido simples em um café espanhol.

“Quisiera…” é um pedido educado. Em muitos lugares da Espanha, “zumo” significa suco.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('es-v1-u2-l2', 'es-v1-unit-2', '2', 'Comida e preferências', 'Objetivo: Expressar gostos e escolher uma refeição.

“Me gusta…” significa “eu gosto”. Para plural, “me gustan” concorda com aquilo de que se gosta.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('es-v1-u2-l3', 'es-v1-unit-2', '3', 'Transporte e direções', 'Objetivo: Perguntar por um lugar e compreender direções simples.

“¿Dónde está…?” pergunta onde está um lugar. “Gira a la derecha” significa vire à direita.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('es-v1-u2-l4', 'es-v1-unit-2', '4', 'Compras e ajuda', 'Objetivo: Perguntar preço e fazer um pedido de ajuda compreensível.

“¿Cuánto cuesta?” pergunta quanto custa. “Necesito ayuda” significa preciso de ajuda.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('ko-v1-u1-l1', 'ko-v1-unit-1', '1', 'Olá e despedidas', 'Objetivo: Reconhecer 안녕하세요 e 안녕히 가세요 em uma conversa curta.

안녕하세요 (annyeonghaseyo) = olá; 감사합니다 (gamsahamnida) = obrigado(a); 안녕히 가세요 (annyeonghi gaseyo) = vá em paz. Em coreano, o Hangul representa sílabas formadas por blocos.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('ko-v1-u1-l2', 'ko-v1-unit-1', '2', 'Sílabas e palavras curtas', 'Objetivo: Ler palavras frequentes em Hangul e reconhecer sua pronúncia complementar.

Leia o bloco inteiro: 가 (ga), 나 (na), 다 (da). As vogais ㅏ (a), ㅓ (eo) e ㅗ (o) têm sons diferentes; a romanização ajuda no início, mas o Hangul é a escrita principal.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('ko-v1-u1-l3', 'ko-v1-unit-1', '3', 'Meu nome e meu país', 'Objetivo: Apresentar-se e informar a origem usando frases educadas.

저는 (jeoneun) = eu; 브라질 (beurajil) = Brasil; 저는 브라질에서 왔어요 (jeoneun beurajileseo wasseoyo) = vim do Brasil. A partícula 에서 marca o lugar de origem da ação.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('ko-v1-u1-l4', 'ko-v1-unit-1', '4', 'Obrigado e por favor', 'Objetivo: Agradecer e pedir algo usando formas comuns de cortesia.

감사합니다 (gamsahamnida) = obrigado(a); 주세요 (juseyo) = por favor, dê-me; 괜찮아요 (gwaenchanayo) = tudo bem. O verbo costuma aparecer no final da frase.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('ko-v1-u2-l1', 'ko-v1-unit-2', '1', 'No café', 'Objetivo: Pedir uma bebida e reconhecer os contadores de copos.

물 (mul) = água; 커피 (keopi) = café; 한 잔 (han jan) = um copo ou uma xícara. Para pedir com educação, use 주세요 (juseyo).', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('ko-v1-u2-l2', 'ko-v1-unit-2', '2', 'Comidas e preferências', 'Objetivo: Reconhecer alimentos e usar 좋아해요 para expressar gosto.

김밥 (gimbap) = rolinho de arroz; 사과 (sagwa) = maçã; 좋아해요 (joahaeyo) = gosto. O verbo aparece no fim da frase.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('ko-v1-u2-l3', 'ko-v1-unit-2', '3', 'Na estação', 'Objetivo: Perguntar a localização de uma estação e entender esquerda/direita.

지하철역 (jihacheol-yeok) = estação de metrô; 어디예요? (eodiyeyo?) = onde fica?; 왼쪽 (oenjjok) = esquerda; 오른쪽 (oreunjjok) = direita.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING'),
('ko-v1-u2-l4', 'ko-v1-unit-2', '4', 'Minha rotina', 'Objetivo: Descrever uma rotina com tempo e ação em frases curtas.

아침 (achim) = manhã; 학교 (hakgyo) = escola; 가요 (gayo) = vou. Em coreano, a ordem comum é tópico, informação e verbo no final.', '30', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING');
create temporary table _tec_lang_exercises (id text, lesson_id text, position int, exercise_type text, instruction text, prompt text, options jsonb, word_bank jsonb, left_items jsonb, right_items jsonb, audio_text text, accepted_answers jsonb, answer_key jsonb, explanation text, content_version int, author text, publication_status text, review_status text, skill_code text, difficulty_level smallint, dialogue_speaker text, dialogue_context jsonb) on commit drop;
do $$ begin
  if exists (select 1 from _tec_lang_courses e join public.tec_english_courses a using (course_code) where row(a.content_version,a.title,a.description,a.author,a.publication_status,a.review_status,a.xp_per_lesson,a.is_test_fixture) is distinct from row(e.content_version,e.title,e.description,e.author,e.publication_status,e.review_status,e.xp_per_lesson,e.is_test_fixture)) then raise exception 'TEC_LANGUAGE_COURSE_CONFLICT'; end if;
  if exists (select 1 from _tec_lang_units e join public.tec_english_units a using (id) where row(a.course_code,a.position,a.title,a.description,a.content_version,a.author,a.publication_status,a.review_status) is distinct from row(e.course_code,e.position,e.title,e.description,e.content_version,e.author,e.publication_status,e.review_status)) then raise exception 'TEC_LANGUAGE_UNIT_CONFLICT'; end if;
  if exists (select 1 from _tec_lang_lessons e join public.tec_english_lessons a using (id) where row(a.unit_id,a.position,a.title,a.introduction,a.xp_reward,a.content_version,a.author,a.publication_status,a.review_status) is distinct from row(e.unit_id,e.position,e.title,e.introduction,e.xp_reward,e.content_version,e.author,e.publication_status,e.review_status)) then raise exception 'TEC_LANGUAGE_LESSON_CONFLICT'; end if;
  if exists (select 1 from _tec_lang_exercises e join public.tec_english_exercises a using (id) where row(a.lesson_id,a.position,a.exercise_type,a.instruction,a.prompt,a.options,a.word_bank,a.left_items,a.right_items,a.audio_text,a.accepted_answers,a.answer_key,a.explanation,a.content_version,a.author,a.publication_status,a.review_status,a.skill_code,a.difficulty_level,a.dialogue_speaker,a.dialogue_context) is distinct from row(e.lesson_id,e.position,e.exercise_type,e.instruction,e.prompt,e.options,e.word_bank,e.left_items,e.right_items,e.audio_text,e.accepted_answers,e.answer_key,e.explanation,e.content_version,e.author,e.publication_status,e.review_status,e.skill_code,e.difficulty_level,e.dialogue_speaker,e.dialogue_context)) then raise exception 'TEC_LANGUAGE_EXERCISE_CONFLICT'; end if;
end $$;
do $$ begin
  if exists (select 1 from _tec_lang_courses e where not exists (select 1 from public.tec_english_courses a where a.course_code=e.course_code and row(a.content_version,a.title,a.description,a.author,a.publication_status,a.review_status,a.xp_per_lesson,a.is_test_fixture) is not distinct from row(e.content_version,e.title,e.description,e.author,e.publication_status,e.review_status,e.xp_per_lesson,e.is_test_fixture))) then raise exception 'TEC_LANGUAGE_COURSE_VERIFY_FAILED'; end if;
  if exists (select 1 from _tec_lang_units e where not exists (select 1 from public.tec_english_units a where a.id=e.id and row(a.course_code,a.position,a.title,a.description,a.content_version,a.author,a.publication_status,a.review_status) is not distinct from row(e.course_code,e.position,e.title,e.description,e.content_version,e.author,e.publication_status,e.review_status))) then raise exception 'TEC_LANGUAGE_UNIT_VERIFY_FAILED'; end if;
  if exists (select 1 from _tec_lang_lessons e where not exists (select 1 from public.tec_english_lessons a where a.id=e.id and row(a.unit_id,a.position,a.title,a.introduction,a.xp_reward,a.content_version,a.author,a.publication_status,a.review_status) is not distinct from row(e.unit_id,e.position,e.title,e.introduction,e.xp_reward,e.content_version,e.author,e.publication_status,e.review_status))) then raise exception 'TEC_LANGUAGE_LESSON_VERIFY_FAILED'; end if;
  if exists (select 1 from _tec_lang_exercises e where not exists (select 1 from public.tec_english_exercises a where a.id=e.id and row(a.lesson_id,a.position,a.exercise_type,a.instruction,a.prompt,a.options,a.word_bank,a.left_items,a.right_items,a.audio_text,a.accepted_answers,a.answer_key,a.explanation,a.content_version,a.author,a.publication_status,a.review_status,a.skill_code,a.difficulty_level,a.dialogue_speaker,a.dialogue_context) is not distinct from row(e.lesson_id,e.position,e.exercise_type,e.instruction,e.prompt,e.options,e.word_bank,e.left_items,e.right_items,e.audio_text,e.accepted_answers,e.answer_key,e.explanation,e.content_version,e.author,e.publication_status,e.review_status,e.skill_code,e.difficulty_level,e.dialogue_speaker,e.dialogue_context))) then raise exception 'TEC_LANGUAGE_EXERCISE_VERIFY_FAILED'; end if;
  if exists (select 1 from _tec_lang_courses c where (select count(*) from public.tec_english_units a where a.course_code=c.course_code) <> (select count(*) from _tec_lang_units e where e.course_code=c.course_code) or (select count(*) from public.tec_english_lessons a join public.tec_english_units u on u.id=a.unit_id where u.course_code=c.course_code) <> (select count(*) from _tec_lang_lessons e join _tec_lang_units u on u.id=e.unit_id where u.course_code=c.course_code) or (select count(*) from public.tec_english_exercises a join public.tec_english_lessons l on l.id=a.lesson_id join public.tec_english_units u on u.id=l.unit_id where u.course_code=c.course_code) <> (select count(*) from _tec_lang_exercises e join _tec_lang_lessons l on l.id=e.lesson_id join _tec_lang_units u on u.id=l.unit_id where u.course_code=c.course_code)) then raise exception 'TEC_LANGUAGE_CONTENT_COUNT_MISMATCH'; end if;
  if exists (select 1 from public.tec_english_courses c join _tec_lang_courses e using (course_code) where c.publication_status <> 'STAGING' or c.review_status <> 'PEDAGOGICAL_REVIEW_PENDING') then raise exception 'TEC_LANGUAGE_CONTENT_NOT_STAGING'; end if;
end $$;
select course_code, content_version, publication_status, review_status, (select count(*) from public.tec_english_units u where u.course_code=c.course_code) as units, (select count(*) from public.tec_english_lessons l join public.tec_english_units u on u.id=l.unit_id where u.course_code=c.course_code) as lessons, (select count(*) from public.tec_english_exercises e join public.tec_english_lessons l on l.id=e.lesson_id join public.tec_english_units u on u.id=l.unit_id where u.course_code=c.course_code) as exercises from _tec_lang_courses c order by course_code;
commit;
